export type Provider = 
/**
 * Ollama on this computer.
 */
{ kind: "ollama"; base_url: string; model: string } | 
/**
 * Claude Code's command-line tool, signed in with the user's own plan.
 * An empty model leaves the choice to the tool.
 */
{ kind: "claude_cli"; model: string } | 
/**
 * OpenAI's Codex command-line tool, signed in with the user's own plan.
 * An empty model leaves the choice to the tool.
 */
{ kind: "codex_cli"; model: string } | 
/**
 * An OpenAI-compatible endpoint with the user's own key: OpenAI, Gemini,
 * Groq, OpenRouter, LM Studio and others. `key` names the key in the
 * operating system's keychain; empty when the endpoint needs none.
 */
{ kind: "open_ai_compatible"; base_url: string; model: string; key: string } | 
/**
 * Anthropic's API with the user's own key.
 */
{ kind: "anthropic"; model: string; key: string }
/**
 * What Seogi needs to do its work, and which of it is in place.
 */
export type Readiness = { 
/**
 * The speech model recordings are transcribed with.
 */
speech_model: string; speech_model_ready: boolean; 
/**
 * The model that tells speakers apart.
 */
diarizer_ready: boolean; 
/**
 * ffmpeg is installed. Needed only for file kinds the built-in decoder
 * cannot read (3gp, amr, wma).
 */
ffmpeg: boolean; ollama_running: boolean; ollama_models: string[]; claude_cli: boolean; codex_cli: boolean; 
/**
 * The model that writes minutes, and whether it can be reached.
 */
summary: string; summary_ready: boolean; 
/**
 * The chosen model was refused, so the tool's own choice writes the
 * minutes until another is picked.
 */
summary_model_refused: boolean; 
/**
 * When the chosen way cannot be used now, the one that writes the
 * minutes instead; `None` when the chosen one can, or when nothing can
 * (then `summary_ready` is false).
 */
summary_fallback: Provider | null; 
/**
 * The models offered for each signed-in tool, the recommended one
 * first.
 */
claude_models: ModelChoice[]; codex_models: ModelChoice[]; vocabulary_path: string; vocabulary_terms: number; library: string; 
/**
 * The Google Drive accounts on this computer, each with the folder
 * for phone recordings it has or would get.
 */
drives: DriveAccount[]; 
/**
 * Where that folder would go on a computer with no Google Drive.
 */
local_inbox: string; 
/**
 * `granted`, `denied`, `not_determined` or `unknown`.
 */
microphone: string }
/**
 * A recent dictation, for the settings screen.
 */
export type RecentDictation = { 
/**
 * The dictation history's own id, for forgetting it.
 */
id: number; text: string; at_ms: number }
/**
 * A recording started or ended.
 */
export type RecordingChanged = { recording: boolean }
/**
 * Recording phase events for windows that follow along (onboarding's Try it).
 */
export type RecordingPhase = 
/**
 * Recording began.
 */
"started" | 
/**
 * The key came up before the hold threshold (or the binding toggles):
 * recording stays on until the next press.
 */
"locked" | 
/**
 * Recording ended; transcription follows.
 */
"stopped" | 
/**
 * The session was cancelled.
 */
"cancelled"
export type RecordingRetentionPeriod = "never" | "preserve_limit" | "days_3" | "weeks_2" | "months_3"
/**
 * The recording in progress, as the screen shows it.
 */
export type RecordingState = { id: string; started_at_ms: number; elapsed_ms: number; 
/**
 * How loud the microphone is right now, 0 to 1.
 */
level: number; 
/**
 * When "중요 표시" was pressed, in milliseconds into the recording.
 */
marks_ms: number[]; device: string; 
/**
 * No sound at all is arriving: the microphone is muted or not allowed.
 */
no_sound: boolean }
export type RecordingStateEvent = { phase: RecordingPhase }
/**
 * A retired ONNX model found on disk.
 */
export type RetiredModel = { id: string; name: string; size_mb: number; replacement_repo: string }
export type SecretMap = Partial<{ [key in string]: string }>
export type Section = { 
/**
 * Short ASCII name the model answers with: `actions`, `decisions`.
 */
key: string; 
/**
 * The heading in the minutes: `액션 아이템`.
 */
title: string; kind: SectionKind; 
/**
 * What belongs in this section, in the model's words.
 */
instruction: string; 
/**
 * How the screen lays it out. Says nothing to the model.
 */
style?: SectionStyle }
export type SectionKind = 
/**
 * A table of tasks: what, who, by when, source time.
 */
"actions" | 
/**
 * A list of statements, each with its source time.
 */
"items" | 
/**
 * A list of things said, quoted as they were said.
 */
"quotes"
/**
 * How a section of the minutes is laid out.
 */
export type SectionStyle = 
/**
 * One ruled line an entry.
 */
"list" | 
/**
 * A row of a table of facts, like the budget or the address. A fact
 * the recording does not give is shown as not said, rather than left
 * out.
 */
"fact"
export type SecureInputStatus = { 
/**
 * Secure input is currently enabled (live check)
 */
enabled: boolean; 
/**
 * Enabled continuously long enough to be considered stuck (not just a
 * password field gaining momentary focus)
 */
sustained: boolean; culprit_pid: number | null; culprit_name: string | null; 
/**
 * Carbon fallback registrations are currently active
 */
fallback_active: boolean; 
/**
 * Binding ids shadow-registered with identical semantics
 */
covered_bindings: string[]; 
/**
 * Side-specific binding ids widened to match either side while shadowed
 */
degraded_bindings: string[]; 
/**
 * Binding ids that cannot fire at all (e.g. fn+key, registration failure)
 */
uncovered_bindings: string[]; 
/**
 * The user tried to record a shortcut while secure input was active.
 * Treated as user impact even when every binding is covered, so the
 * warning banner appears and explains why recording refused.
 */
recorder_blocked: boolean }
/**
 * One stretch of speech by one speaker. Times are milliseconds from the
 * start of the original recording, so any line can be played back from it.
 */
export type Segment = { start_ms: number; end_ms: number; 
/**
 * The speaker's number, from 1; 0 when the speaker is not known.
 */
speaker: number; text: string; 
/**
 * How sure the speech model was of this line, 0 to 1, when it says.
 */
confidence?: number | null; 
/**
 * The speech model's own measures say this line may be wrong: worth a
 * listen before it is relied on.
 */
unsure?: boolean; 
/**
 * Someone else talks over most of this line, so the words may be a mix
 * of two people.
 */
overlap?: boolean }
/**
 * How the transcribe shortcut's key events drive a recording.
 */
export type ShortcutActivation = 
/**
 * Press to start, press again to stop.
 */
"toggle" | 
/**
 * Hold to record, release to stop.
 */
"push_to_talk" | 
/**
 * Hold to record and release to stop, or tap to keep recording until the
 * next press. Which one it was is decided by how long the key was held
 * (`hold_threshold_ms`).
 */
"hold_or_toggle"
export type ShortcutBinding = { id: string; name: string; description: string; default_binding: string; current_binding: string }
/**
 * A document that could not be read.
 */
export type Skipped = { 
/**
 * Its file name.
 */
file: string; 
/**
 * `kind` (not a kind read here), `unreadable`, `no_text` (a scanned
 * PDF), or `pictures_local` (pictures are not shown to a model on this
 * computer or one behind a key).
 */
reason: string }
export type SoundTheme = "marimba" | "pop" | "custom"
/**
 * Where in the recording an entry comes from.
 */
export type Source = { 
/**
 * Milliseconds into the original recording.
 */
ms: number; 
/**
 * The words it rests on, as transcribed.
 */
quote: string }
/**
 * A speaker in one recording. The name starts as "화자 N" and is the
 * user's to change.
 */
export type Speaker = { id: number; name: string }
/**
 * One speaker's share of the talking.
 */
export type SpeakerTalk = { 
/**
 * The speaker's number in the transcript; the name is read from it
 * where it is shown, so renaming a speaker carries over.
 */
speaker: number; talk_ms: number; 
/**
 * Of everyone's talking, 0 to 100.
 */
share: number; 
/**
 * Times the speaker took the floor.
 */
turns: number; 
/**
 * The longest stretch the speaker talked alone, and where it began.
 */
longest_ms: number; longest_at_ms: number; 
/**
 * Lines ending in a question.
 */
questions: number; 
/**
 * Times the speaker took over before the one talking had finished.
 */
cut_ins: number }
/**
 * Where a tool stands on this computer.
 */
export type SignIn = 
/**
 * The tool is not installed.
 */
"missing" | 
/**
 * Installed, not signed in.
 */
"signed_out" | 
/**
 * Installed and signed in.
 */
"signed_in"
/**
 * Where both tools stand.
 */
export type SignIns = { claude: SignIn; codex: SignIn }
/**
 * A speech model the user can pick for dictation.
 */
export type SpeechChoice = { id: string; label: string; downloaded: boolean; size_mb: number; speed: Speed; 
/**
 * Among the most accurate for Korean.
 */
accurate: boolean; recommended: boolean }
/**
 * How quick a choice is for dictation, where the words should be in within
 * a second or two of the last one spoken.
 */
export type Speed = "fast" | "fair" | "slow"
/**
 * A place on the screen, in logical pixels.
 */
export type Spot = { x: number; y: number }
/**
 * What happened along the way, for the log and for honest reporting.
 */
export type Stats = { audio_ms: number; 
/**
 * How much of the audio is speech.
 */
speech_ms: number; chunks: number; 
/**
 * Chunks the speech model could not transcribe, and so are missing.
 */
failed_chunks: number; 
/**
 * Lines dropped as made up over silence.
 */
dropped_lines: number; 
/**
 * Places in the text the user's vocabulary corrected.
 */
corrected: number; diarized: boolean; 
/**
 * Why speakers were not told apart, when they were asked to be.
 */
diarize_skipped: string | null; 
/**
 * The most speakers the diarization model can tell apart.
 */
max_speakers: number; vad_ms: number; diarize_ms: number; transcribe_ms: number }
export type Status = 
/**
 * Being recorded in the app right now.
 */
"recording" | 
/**
 * Waiting its turn to be processed.
 */
"queued" | 
/**
 * Being transcribed or written up; `stage` and `percent` say how far.
 */
"working" | 
/**
 * Transcribed, and the minutes are still to come: the summary model
 * could not be reached and will be tried again.
 */
"transcribed" | 
/**
 * The minutes are written.
 */
"done" | 
/**
 * It could not be processed; `error` says why.
 */
"failed"
/**
 * A part of the meeting told as a story: a short heading and a paragraph,
 * with the times in the recording its sentences rest on.
 */
export type StoryPart = { title: string; text: string; sources: Source[] }
/**
 * Phase of the streaming overlay card, emitted to drive its UI state.
 */
export type StreamPhase = 
/**
 * Receiving audio / live text (or waiting for the stream to begin). Rust
 * does not emit this today; the frontend starts in this phase and Rust only
 * emits transitions away from it.
 */
"listening" | 
/**
 * Finalizing or post-processing — show a spinner.
 */
"working"
/**
 * Emitted to switch the streaming overlay to a working spinner.
 */
export type StreamPhaseEvent = { phase: StreamPhase; 
/**
 * Present only when `phase` is `Working`.
 */
kind?: StreamWorkKind | null }
/**
 * Live transcription snapshot emitted to the overlay during a streaming run.
 * `committed` is the append-only, flicker-free prefix; `tentative` is the
 * volatile suffix the model may still rewrite.
 */
export type StreamTextEvent = { committed: string; tentative: string }
/**
 * Semantic kind of "working" phase, used to localize the spinner label.
 */
export type StreamWorkKind = "transcribing" | "polishing"
/**
 * What one short request to the minutes model gave.
 */
export type SummaryTry = { ok: boolean; 
/**
 * How long it took, in milliseconds.
 */
ms: number; 
/**
 * The model the answer came from, as the minutes footer names it.
 */
model: string; 
/**
 * Why it failed, in the words of `llm::trouble_code`; empty when it
 * worked.
 */
trouble: string }
/**
 * Keys someone else answers to.
 */
export type TakenKeys = { keys: string; 
/**
 * `handy`, `record` or `mark`.
 */
by: string }
export type TalkStats = { 
/**
 * The speakers, the one who talked most first.
 */
speakers: SpeakerTalk[]; 
/**
 * The clearest moments of taking over, in the order they happened.
 */
moments: CutIn[] }
export type Template = { id: string; 
/**
 * Shown to the user: `회의`, `고객 상담`.
 */
name: string; 
/**
 * When this template fits; the classifier reads it too.
 */
description: string; 
/**
 * What to look for in this kind of recording, added to the base rules.
 */
guidance?: string; 
/**
 * Whether the minutes carry feedback on the conversation itself: how
 * the talking went, measured, and what went well and less well. On for
 * consultations; a template's data can turn it off.
 */
feedback?: boolean; sections: Section[]; 
/**
 * The summary model for this template, when it should differ from the
 * user's default (`ollama gemma3:27b`). Empty for the default.
 */
model?: string }
/**
 * What the documents gave.
 */
export type TermsFound = { terms: string[]; 
/**
 * Documents that gave nothing, and why.
 */
skipped: Skipped[] }
/**
 * UI appearance mode. `System` follows the OS `prefers-color-scheme`; `Light`
 * and `Dark` force one of the two palettes Handy already ships.
 */
export type Theme = "system" | "light" | "dark"
/**
 * A way to tidy the words.
 */
export type TidyChoice = { provider: Provider; label: string; speed: Speed; 
/**
 * How long it took the last time it was used here, in milliseconds.
 */
last_ms: number | null; 
/**
 * It uses the user's plan or key, which can run out.
 */
metered: boolean }
/**
 * How an event's title is read. The first rule whose pattern matches wins.
 * 
 * `pattern` is a regular expression; its named groups can be used as
 * `{name}` in `title`, `place` and `mentions`.
 */
export type TitleRule = { pattern: string; 
/**
 * The minutes template for such events; empty lets the content decide.
 */
template?: string; 
/**
 * The meeting's title; empty keeps the event's title as it is.
 */
title?: string; place?: string; 
/**
 * Names in the title that the speech model should know: a customer, a
 * company.
 */
mentions?: string[] }
/**
 * A tool that signs in with the user's own plan.
 */
export type Tool = 
/**
 * Claude Code, for a Claude plan.
 */
"claude" | 
/**
 * Codex, for a ChatGPT plan.
 */
"codex"
export type TranscribeAcceleratorSetting = "auto" | "cpu" | "gpu"
export type Transcript = { 
/**
 * The language the recording was transcribed in (`ko`).
 */
language: string; 
/**
 * The model that transcribed it.
 */
model: string; segments: Segment[]; speakers: Speaker[]; 
/**
 * Words the user's vocabulary corrected in the text.
 */
corrections?: Corrected[] }
/**
 * Emitted when a dictation finishes (not on cancel); onboarding uses it to measure speed.
 */
export type TranscriptionCompleteEvent = { outcome: TranscriptionOutcome; audio_seconds: number; wait_seconds: number }
/**
 * A background transcription of one History entry.
 */
export type TranscriptionJob = { entry_id: number; status: TranscriptionJobStatus }
export type TranscriptionJobStatus = 
/**
 * Waiting behind another job.
 */
{ state: "queued" } | 
/**
 * `percent` of the audio is transcribed.
 */
{ state: "running"; percent: number } | 
/**
 * The entry has its new text, or the job was cancelled.
 */
{ state: "finished" } | { state: "failed"; error: string }
/**
 * How a dictation ended.
 */
export type TranscriptionOutcome = 
/**
 * The text was typed.
 */
"typed" | 
/**
 * Nothing was heard, so nothing was typed.
 */
"empty" | 
/**
 * The microphone sent only digital silence (e.g. muted).
 */
"silent" | 
/**
 * Transcribing or pasting failed.
 */
"failed"
/**
 * How the words reach the cursor.
 */
export type Typing = 
/**
 * Pasted at once; what was on the clipboard is put back.
 */
"paste" | 
/**
 * Typed letter by letter, for the few places that refuse a paste.
 */
"type" | 
/**
 * Only copied, for the user to paste themselves.
 */
"copy"
export type TypingTool = "auto" | "wtype" | "kwtype" | "dotool" | "ydotool" | "xdotool"
/**
 * A calendar event of today, for the band at the top.
 */
export type Upcoming = { event: Event; 
/**
 * The user turned its reminder off.
 */
muted: boolean }
export type VadBackend = "silero" | "earshot"
/**
 * A folder watched for new recordings.
 */
export type WatchedFolder = { path: string; enabled?: boolean; 
/**
 * The minutes template for recordings from this folder; empty lets the
 * calendar or the content decide.
 */
template_id?: string; 
/**
 * When watching began (milliseconds since 1970 UTC). Recordings in the
 * folder from before then are left for the user to bring in; anything
 * that arrives later is taken, whatever date the file itself carries.
 * 0 takes everything.
 */
since_ms?: number }
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
